function i(t){const n=new Date(t),o=new Date().getTime()-n.getTime(),e=Math.floor(o/6e4);if(e<1)return"just now";if(e<60)return`${e} min${e===1?"":"s"} ago`;const a=Math.floor(e/60);if(a<24)return`${a} hr${a===1?"":"s"} ago`;const r=Math.floor(a/24);return`${r} day${r===1?"":"s"} ago`}function f(t){return new Date(t).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",hour12:!1})}function c(t){const n=new Date(t),o=new Date().getTime()-n.getTime(),e=Math.floor(o/36e5),a=Math.floor(o%36e5/6e4);return`${e}h ${a}m`}function u(t){return t?new Date(t)<new Date:!1}function w(t,n=60){if(!t)return!1;const s=new Date(t),o=new Date,e=s.getTime()-o.getTime();return e>0&&e<=n*6e4}export{i as a,c as b,w as c,f,u as i};
